<div class="mt-5 grid gap-4 md:grid-cols-2 xl:grid-cols-3"><?php foreach($workspaces as$w): ?><article class="rounded-2xl bg-[#e7f2ef] p-4 shadow-insetsoft"><div class="flex items-start justify-between"><span class="grid h-10 w-10 place-items-center rounded-xl bg-white text-sea"><i data-lucide="building-2" class="h-5"></i></span><span class="rounded-full bg-white px-2 py-1 text-[10px] font-bold uppercase text-mint"><?= esc($w['status']) ?></span></div><h4 class="mt-4 font-extrabold"><?= esc($w['company_name']?:$w['name']) ?></h4><p class="text-xs text-[#78908c]"><?= esc(trim(($w['first_name']??'').' '.($w['last_name']??''))?:($w['email']??'No owner')) ?></p><div class="mt-4 flex gap-4 text-xs"><span><b><?= number_format($w['contacts_count']??0) ?></b> contacts</span><span><b><?= number_format($w['campaigns_count']??0) ?></b> campaigns</span></div><form action="<?= portal_url('clients/'.$w['uuid'].'/open') ?>" method="post" class="mt-4"><?= csrf_field() ?><button class="btn btn-primary w-full justify-center">Open workspace</button></form></article><?php endforeach ?><?php if(!$workspaces): ?><p class="col-span-full rounded-xl bg-[#e7f2ef] p-5 text-sm text-[#78908c]">No customer workspace is assigned yet.</p><?php endif ?></div>
